     • Paste this entire HTML into a Custom HTML block
     • Set page template to "Full Width" or "No Sidebar"

     OPTION B – Convert to a proper WordPress theme:
     • Hand this file to a developer to convert to a child theme
     • Wrap the <body> content in a page.php template
     • Move <style> to style.css and functions.php

  3. CONTACT FORM
     - Install "Contact Form 7" or "Gravity Forms" plugin
     - Replace the static form HTML with the plugin's shortcode
     - Connect form submissions to your campaign email

  4. DOMAIN POINTING (GoDaddy)
     - In GoDaddy DNS settings, point www.EdBannon.com to your WordPress hosting IP
     - Or if using GoDaddy Managed WordPress: install WP, then point the domain
       in the GoDaddy dashboard under "My Products > Websites + Marketing"

  5. SEO
     - Install Yoast SEO plugin
     - Set page title: "Ed Bannon for CPS Board of Education District 1A"
     - Meta description: "Ed Bannon is running for CPS Board of Education District 1A.
       A lifelong NW Sider and Dever LSC member, Ed puts students first."
  ═══════════════════════════════════════════════════════════════
-->"},"elements":[],"widgetType":"text-editor"}],"isInner":false}]

item.content:encoded:
{"styles":{"css":"/* PLATFORM — FULL-WIDTH SECTION */
.wp-block-group.priorities-section.alignfull {
 background-color: #FFFFFF !important;
 padding: 48px 32px 56px !important;
 box-sizing: border-box !important;
}

/* PLATFORM — HEADER TYPOGRAPHY */
.priorities-eyebrow {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: 0.85rem !important;
 line-height: 1 !important;
 font-weight: 700 !important;

 letter-spacing: 0.28em !important;
 text-transform: uppercase;

 color: #D4192C !important;
}

.priorities-heading {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: clamp(2.6rem, 4vw, 3.8rem) !important;
 line-height: 0.95 !important;
 font-weight: 900 !important;

 text-transform: uppercase;
 letter-spacing: 0 !important;

 color: #1A1A1A !important;
}

.priority-card {
 background: #F7F2E8;
 border-radius: 14px;
 padding: 18px 20px;
 box-sizing: border-box;
 min-height: 0;

 border-top: 1px solid rgba(26, 26, 26, 0.05);
 border-right: 1px solid rgba(26, 26, 26, 0.05);
 border-bottom: 1px solid rgba(26, 26, 26, 0.08);

 box-shadow: 0 4px 10px rgba(0, 0, 0, 0.08);
}

/* PLATFORM CARD COPY — MATCH ED IN THE NEIGHBORHOOD */
.priority-card p {
 font-family: "Inter", sans-serif !important;
 font-size: 1rem !important;
 line-height: 1.55 !important;
 font-weight: 400 !important;
 color: #5A5A5A !important;
}

.priority-red {
 border-left: 4px solid #D4192C;
}

.priority-blue {
 border-left: 4px solid #00A8E0;
}

/* PLATFORM — TABLET */
@media (max-width: 900px) {
 .wp-block-group.priorities-section.alignfull {
 padding: 64px 24px 72px !important;
 }
}

/* PLATFORM — MOBILE */
@media (max-width: 700px) {

.wp-block-group.priorities-section.alignfull {
 padding: 40px 24px 48px !important;
 }

 /* Extend white background through the right edge */
 .priorities-section {
 background-color: #FFFFFF !important;
 box-shadow: 0 0 0 100vmax #FFFFFF !important;
 clip-path: inset(0 -100vmax);
}

 .priorities-inner {
 width: 100% !important;
 max-width: none !important;
 margin-left: auto !important;
 margin-right: auto !important;
 }

 .priorities-inner .is-layout-grid {
 display: grid !important;
 grid-template-columns: 1fr !important;
 gap: 22px !important;
 }

 .priority-card {
 width: 100% !important;
 max-width: none !important;
 min-width: 0 !important;
 min-height: 0 !important;
 padding: 26px !important;
 box-sizing: border-box !important;
 }
}


.about-section {
 width: 100vw !important;
 max-width: none !important;
 margin-left: 50% !important;
 transform: translateX(-50%);

 position: relative;
 overflow: hidden;
 box-sizing: border-box;

 background-color: #F7F2E8;
 background-image:
 linear-gradient(
 rgba(247, 242, 232, 0.88),
 rgba(247, 242, 232, 0.88)
 ),
 url("https://edbannon.com/wp-content/uploads/2026/08/District-Map-3072-x-2049-px-scaled.png");

background-repeat: no-repeat;
background-position: center -70px;
background-size: 1600px auto;

padding: 48px 32px 56px;
}

.about-inner {
 width: 80% !important;
 max-width: 1400px !important;
 margin: 0 auto !important;

 position: relative;
 z-index: 1;
}

.about-photo-stage {
 position: relative;
 width: 560px;
 max-width: 90%;
 height: 470px;
 margin: 8px auto 18px;
}

/* Blue rounded rectangle behind Ed */
.about-photo-stage::before {
 content: "";
 position: absolute;

 width: 410px;
 height: 390px;

 top: -16px;
 left: 50px;

 background-color: rgba(0, 168, 224, 0.18);
 border-radius: 24px;

 z-index: 1;
}

/* Ed's About-section portrait */
.about-headshot {
 position: absolute !important;
 width: 445px !important;
 height: auto !important;

 top: 0;
 left: 0;

 z-index: 2;
 margin: 0 !important;
}

/* Gold star in upper-right */
.about-star {
 position: absolute !important;
 width: 52px !important;
 height: auto !important;

 top: -10px;
 right: -40px;

 z-index: 3;
 margin: 0 !important;
 pointer-events: none;
}

/* ABOUT — PHOTO INTRO LINE */
.about-kicker {
 width: fit-content !important;
 margin: -18px auto 10px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: clamp(2.8rem, 4.3vw, 4.1rem) !important;
 line-height: 0.95 !important;
 font-weight: 500 !important;
 letter-spacing: 0.05em !important;
 text-transform: uppercase !important;
 text-align: center !important;
 color: #D4192C !important;
}

.about-kicker strong {
 font-weight: 900 !important;
}

/* ABOUT — MATCH PLATFORM TYPOGRAPHY */
.about-eyebrow {
 margin: 0 0 18px !important;
 font-family: "Barlow Condensed", sans-serif !important;
 font-size: 0.85rem !important;
 line-height: 1 !important;
 font-weight: 700 !important;
 letter-spacing: 0.28em !important;
 text-transform: uppercase !important;
 color: #D4192C !important;
}

.about-heading {
 margin: 0 0 18px !important;
 font-family: "Barlow Condensed", sans-serif !important;
 font-size: clamp(2.6rem, 4vw, 3.8rem) !important;
 line-height: 0.95 !important;
 font-weight: 900 !important;
 text-transform: uppercase !important;
 letter-spacing: 0 !important;
 color: #1A1A1A !important;
}

/* About Ed heading + biography */
.about-copy-area {
 position: relative;
 z-index: 2;

 width: 80vw !important;
 max-width: 1400px !important;

 margin-left: 50% !important;
 transform: translateX(-50%) !important;

 margin-top: -60px !important;
}

.about-credentials-grid {
 width: 700px !important;
 max-width: calc(100% - 40px) !important;
 margin: 32px auto 0 !important;

 display: grid !important;
 grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
 column-gap: 64px !important;
 row-gap: 28px !important;
}

.about-credential {
 background: #FFFFFF;
 border-radius: 12px;
 padding: 18px 20px;
 box-sizing: border-box;
 box-shadow: 0 3px 8px rgba(0, 0, 0, 0.07);
}

.about-credential.credential-red {
 border: 1.5px solid rgba(212, 25, 44, 0.25) !important;
}

.about-credential.credential-blue {
 border: 1.5px solid rgba(0, 168, 224, 0.25) !important;
}

@media (max-width: 700px) {

 .about-section {
 padding: 40px 24px 48px !important;
 }

 .about-inner {
 width: 100% !important;
 max-width: none !important;
 margin-left: auto !important;
 margin-right: auto !important;
 }

.about-copy-area {
 width: 100% !important;
 max-width: none !important;

 margin-left: 0 !important;
 transform: none !important;
}

 .about-credentials-grid {
 width: calc(100% - 24px) !important;
 max-width: 700px !important;
 grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
 column-gap: 20px !important;
 row-gap: 20px !important;
 }

 .about-credential {
 padding: 16px;
 }

 .about-star {
 width: 40px !important;
 top: -6px;
 right: -8px;
 }
}

/* ABOUT — TABLET + MOBILE SPACING FIX */
@media (max-width: 900px) {

 .about-copy-area {
 margin-top: 0 !important;
 }

 .about-photo-stage {
 margin-bottom: 28px !important;
 }
}

/* ==================================================
 ENDORSEMENTS
 ================================================== */


/* FULL-WIDTH SECTION */
.endorsements-section {
 width: 100vw !important;
 max-width: none !important;

 margin-left: 50% !important;
 transform: translateX(-50%);

 background-color: rgba(0, 168, 224, 0.18) !important;

 padding: 72px 32px 80px;
 box-sizing: border-box;
}


/* INNER CONTENT WIDTH */
.endorsements-inner {
 width: min(1200px, 100%) !important;
 max-width: 1200px !important;

 margin-left: auto !important;
 margin-right: auto !important;
}


/* 3-COLUMN GRID */
.endorsement-post-grid {
 width: 100% !important;
 max-width: 1080px !important;

 margin: 40px auto 0 !important;
 padding: 0 !important;

 display: grid !important;
 grid-template-columns: repeat(3, minmax(0, 1fr)) !important;

 column-gap: 30px !important;
 row-gap: 26px !important;

 align-items: stretch !important;
}


/* INDIVIDUAL CARD */
.endorsement-post-grid > li {
 background-color: #FFFFFF !important;

 border: 1px solid rgba(26, 26, 26, 0.08) !important;
 border-radius: 12px !important;

 /*
 * Compact like the Figma,
 * but allowed to grow if a quote exists.
 */
 min-height: 175px !important;
 height: auto !important;

 padding: 18px 22px !important;
 margin: 0 !important;

 box-sizing: border-box;
 list-style: none;

 display: flex !important;
 flex-direction: column !important;
 align-items: center !important;
 justify-content: center !important;

 text-align: center;

 box-shadow: 0 3px 8px rgba(0, 0, 0, 0.05);
}


/* FEATURED IMAGE / LOGO AREA */
.endorsement-post-grid .wp-block-post-featured-image {
 width: 100% !important;
 height: 100px !important;

 margin: 0 0 10px !important;
 padding: 0 !important;

 display: flex !important;
 align-items: center !important;
 justify-content: center !important;
}


/* LOGO */
.endorsement-post-grid .wp-block-post-featured-image img {
 width: auto !important;
 height: auto !important;

 max-width: 190px !important;
 max-height: 96px !important;

 object-fit: contain !important;

 display: block !important;
 margin: 0 auto !important;
}


/* ENDORSER / ORGANIZATION NAME */
.endorsement-post-grid .wp-block-post-title {
 margin: 0 !important;
 padding: 0 !important;

 font-family: "Barlow Condensed", sans-serif !important;

 font-size: 1rem !important;
 line-height: 1.08 !important;
 font-weight: 700 !important;

 letter-spacing: 0.015em !important;

 text-transform: uppercase;
 text-align: center;

 color: #1A1A1A !important;
}


/* OPTIONAL TITLE / ORGANIZATION */
.endorsement-role {
 margin: 5px 0 0 !important;
 padding: 0 !important;

 font-family: "Inter", sans-serif !important;

 font-size: 0.75rem !important;
 line-height: 1.3 !important;
 font-weight: 400 !important;

 text-align: center;

 color: #5A5A5A !important;
}


/* OPTIONAL ENDORSEMENT QUOTE */
.endorsement-quote {
 margin: 8px 0 0 !important;
 padding: 0 !important;

 font-family: "Inter", sans-serif !important;

 font-size: 0.76rem !important;
 line-height: 1.35 !important;
 font-weight: 400 !important;

 text-align: center;

 color: #5A5A5A !important;

 /*
 * No fixed height or line clamp.
 * Quotes can grow instead of being cut off.
 */
 overflow: visible !important;
}


/* REMOVE EMPTY OPTIONAL FIELDS */
.endorsement-role:empty,
.endorsement-quote:empty {
 display: none !important;
}


/* TABLET */
@media (max-width: 900px) {

 .endorsement-post-grid {
 grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

 column-gap: 24px !important;
 row-gap: 24px !important;
 }
}


/* MOBILE */
@media (max-width: 600px) {

 .endorsements-section {
 padding: 56px 24px 64px;
 }

 .endorsement-post-grid {
 grid-template-columns: 1fr !important;
 gap: 20px !important;
 }

 .endorsement-post-grid > li {
 min-height: 165px !important;
 }

 .endorsement-post-grid .wp-block-post-featured-image {
 height: 78px !important;
 }

 .endorsement-post-grid .wp-block-post-featured-image img {
 max-width: 140px !important;
 max-height: 76px !important;
 }
}

/* ==================================================
 COMMUNITY SECTION
 ================================================== */

.community-section {
 width: 100vw !important;
 max-width: none !important;

 margin-left: 50% !important;
 transform: translateX(-50%);

 background: #FFFFFF !important;

 padding: 72px 32px 88px;
 box-sizing: border-box;
}


/* INNER WIDTH */
.community-inner {
 width: min(1400px, calc(100vw - 64px)) !important;
 max-width: none !important;

 margin: 0 auto !important;
}


/* KEEP CHILDREN FROM GETTING RE-CONSTRAINED */
.community-inner > * {
 max-width: none !important;
}


/* SMALL RED EYEBROW */
.community-eyebrow {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: 0.85rem !important;
 line-height: 1 !important;
 font-weight: 700 !important;

 letter-spacing: 0.28em !important;
 text-transform: uppercase;

 color: #D4192C !important;
}


/* MAIN HEADING */
.community-heading {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: clamp(2.6rem, 4vw, 3.8rem) !important;
 line-height: 0.95 !important;
 font-weight: 900 !important;

 text-transform: uppercase;
 letter-spacing: 0 !important;

 color: #1A1A1A !important;
}


/* INTRO PARAGRAPH */
.community-intro {
 max-width: 900px !important;

 margin: 0 0 10px !important;

 font-family: "Inter", sans-serif !important;
 font-size: 1rem !important;
 line-height: 1.55 !important;

 color: #5A5A5A !important;
}


/* ==================================================
 SLIDER CONTROLS — SIDE ARROWS
 ================================================== */

.community-inner {
 position: relative;
}

.community-slider {
 position: relative;

 width: 100% !important;
 max-width: none !important;

 overflow: hidden;

 padding-left: 64px;
 padding-right: 64px;
 box-sizing: border-box;

 margin-top: 0;
}

.community-slider-controls {
 position: absolute;
 inset: 0;
 pointer-events: none;
 z-index: 5;
}

.community-slider-controls button {
 position: absolute;
 top: 48%;
 transform: translateY(-50%);

 width: 48px;
 height: 48px;

 padding: 0;

 border: 1.5px solid #1A1A1A;
 border-radius: 50%;

 background: #FFFFFF;
 color: #1A1A1A;

 font-size: 1.35rem;
 line-height: 1;

 cursor: pointer;

 display: flex;
 align-items: center;
 justify-content: center;

 pointer-events: auto;

 box-shadow: 0 3px 8px rgba(0,0,0,.12);
}

.community-prev {
 left: -18px;
}

.community-next {
 right: -18px;
}

.community-slider-controls button:hover {
 background: #F7F2E8;
}


/* ==================================================
 COMMUNITY HIGHLIGHTS SLIDER
 ================================================== */

.community-slider {
 width: 100% !important;
 max-width: none !important;

 overflow: hidden;

 margin-top: 0;
}


/* HORIZONTAL TRACK */
.community-slider-track {
 width: 100% !important;

 display: flex !important;
 flex-wrap: nowrap !important;

 gap: 28px !important;

 overflow-x: auto !important;
 overflow-y: hidden !important;

 scroll-behavior: smooth;
 scroll-snap-type: x mandatory;

 padding: 4px 2px 20px !important;
 margin: 0 !important;

 scrollbar-width: none;
}


.community-slider-track::-webkit-scrollbar {
 display: none;
}


/* TWO LARGE ITEMS AT A TIME */
.community-slider-track > li {
 flex: 0 0 calc((100% - 28px) / 2) !important;

 min-width: 0 !important;

 margin: 0 !important;
 padding: 0 !important;

 list-style: none;

 scroll-snap-align: start;
}


/* ==================================================
 FEATURED IMAGE
 ================================================== */

.community-slider-track .wp-block-post-featured-image {
 width: 100% !important;

 aspect-ratio: 16 / 10;

 margin: 0 0 16px !important;
 padding: 0 !important;

 border-radius: 16px;
 overflow: hidden;

 box-shadow: 0 4px 10px rgba(0,0,0,.08);
}


.community-slider-track .wp-block-post-featured-image img {
 width: 100% !important;
 height: 100% !important;

 object-fit: cover !important;

 display: block !important;
}


/* ==================================================
 TITLE
 ================================================== */

.community-slider-track .wp-block-post-title {
 margin: 0 !important;
 padding: 0 !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: 1.35rem !important;
 line-height: 1.05 !important;
 font-weight: 700 !important;

 letter-spacing: 0.01em !important;
 text-transform: uppercase;

 color: #1A1A1A !important;
}


/* ==================================================
 CAPTION
 ================================================== */

.community-caption {
 margin: 7px 0 0 !important;
 padding: 0 !important;

 font-family: "Inter", sans-serif !important;
 font-size: 0.9rem !important;
 line-height: 1.4 !important;
 font-weight: 400 !important;

 color: #5A5A5A !important;
}


.community-caption:empty {
 display: none !important;
}


/* ==================================================
 DESKTOP-HERO-COPY-UP-2026
 MOVE COPY UP — LEAVE BUTTONS FIXED
 ================================================== */

@media (min-width: 1251px) {

 .hero-name,
 .hero-office,
 .hero-copy .wp-block-group:has(> .hero-callout),
 .hero-intro {
 translate: 0 -22px !important;
 }

}


/* ==================================================
 DESKTOP-HANDWRITTEN-LEFT-NUDGE-2026
 ================================================== */

@media (min-width: 1251px) {

 .hero-handwritten {
 translate: -8px 0 !important;
 }

}


/* ==================================================
 HERO BUTTONS — REMOVE ARROWS EVERYWHERE
 ================================================== */

.hero-copy .hero-buttons-row .wp-block-button__link::after {
 content: none !important;
 display: none !important;
}


/* ==================================================
 TABLET
 ================================================== */

@media (max-width: 900px) {

 .community-section {
 padding: 64px 24px 72px;
 }

 .community-inner {
 width: calc(100vw - 48px) !important;
 }

 .community-slider-track {
 gap: 20px !important;
 }

 .community-slider-track > li {
 flex: 0 0 calc((100% - 20px) / 2) !important;
 }

 .community-slider-track .wp-block-post-featured-image {
 aspect-ratio: 4 / 3;
 }
}


/* ==================================================
 MOBILE
 ================================================== */

@media (max-width: 650px) {

 .community-section {
 padding: 56px 24px 64px;
 }

 .community-inner {
 width: 100% !important;
 }

 .community-slider-controls {
 margin: 16px 0;
 }

 .community-slider-controls button {
 width: 42px;
 height: 42px;
 }

 .community-slider-track {
 gap: 18px !important;
 }

 .community-slider-track > li {
 flex: 0 0 100% !important;
 }

 .community-slider-track .wp-block-post-featured-image {
 aspect-ratio: 4 / 3;
 }

 .community-slider-track .wp-block-post-title {
 font-size: 1.2rem !important;
 }

 .community-caption {
 font-size: 0.85rem !important;
 }
}

/* ==================================================
 ALIGN ALL SECTION CONTENT
 ================================================== */

/* PLATFORM — CANVA-STYLE DESKTOP WIDTH */
.priorities-inner {
 width: 80% !important;
 max-width: 1400px !important;
 margin-left: auto !important;
 margin-right: auto !important;
}

/* LEAVE THESE SECTIONS AT THEIR CURRENT WIDTH FOR NOW */
.endorsements-inner,
.community-inner {
 width: min(1400px, calc(100vw - 160px)) !important;
 max-width: 1400px !important;
 margin-left: auto !important;
 margin-right: auto !important;
}

@media (max-width: 900px) {
 .priorities-inner {
 width: 100% !important;
 max-width: none !important;
 }

 .endorsements-inner,
 .community-inner {
 width: calc(100vw - 48px) !important;
 }
}

/* ==================================================
 INTERACTIVE VOTE BANNER
 ================================================== */

.vote-banner {
 width: 100vw !important;
 max-width: none !important;

 margin-left: 50% !important;
 transform: translateX(-50%);

 background-color: #00A8E0 !important;

 padding: 48px 32px 52px !important;
 box-sizing: border-box;

 text-align: center;
 cursor: pointer;
 overflow: hidden;
}

.vote-cycle {
 width: 100%;
 text-align: center;
 cursor: pointer;
 user-select: none;
}

.vote-kicker {
 margin-bottom: 9px;

 font-family: "Barlow Condensed", sans-serif;
 font-size: 0.78rem;
 line-height: 1;
 font-weight: 600;

 letter-spacing: 0.28em;
 text-transform: uppercase;

 color: rgba(255,255,255,.65);
}

.vote-word {
 font-family: "Barlow Condensed", sans-serif;
 font-size: 126px;
 line-height: 0.88;
 font-weight: 900;

 text-transform: uppercase;
 color: #FFFFFF;

 transition:
 opacity 0.15s ease,
 transform 0.15s ease;
}

.vote-word.is-changing {
 opacity: 0;
 transform: scale(.96);
}

.vote-instruction {
 margin-top: 14px;

 font-family: "Barlow Condensed", sans-serif;
 font-size: 0.9rem;
 line-height: 1;
 font-weight: 600;

 letter-spacing: 0.22em;
 text-transform: uppercase;

 color: rgba(255,255,255,.65);
}

.vote-cycle,
.vote-cycle:hover,
.vote-cycle:focus,
.vote-cycle:active {
 border: none !important;
 outline: none !important;
 box-shadow: none !important;
}

.vote-banner {
 position: relative;
}

.vote-star {
 position: absolute !important;

 width: 260px !important;
 height: auto !important;

 right: 10px;
 top: 50%;
 transform: translateY(-50%);

 margin: 0 !important;

 opacity: 0.42;
 pointer-events: none;

 z-index: 1;
}

/* ==================================================
 GET INVOLVED
 ================================================== */

.get-involved-section {
 width: 100vw !important;
 max-width: none !important;

 margin-left: 50% !important;
 transform: translateX(-50%);

 background-color: #F7F2E8 !important;

 padding: 76px 32px 84px !important;
 box-sizing: border-box;
}

.get-involved-inner {
 width: min(1400px, calc(100vw - 160px)) !important;
 max-width: 1400px !important;

 margin: 0 auto !important;
}


/* EYEBROW */
.get-involved-eyebrow {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: 0.85rem !important;
 line-height: 1 !important;
 font-weight: 700 !important;

 letter-spacing: 0.28em !important;
 text-transform: uppercase;

 color: #D4192C !important;
}


/* HEADING */
.get-involved-heading {
 margin: 0 0 18px !important;

 font-family: "Barlow Condensed", sans-serif !important;
 font-size: clamp(2.6rem, 4vw, 3.8rem) !important;
