 margin-block-start: -24px !important;
 margin-block-end: 0 !important;

 min-height: 0 !important;
}

.district-banner {
 margin-top: 0 !important;
 margin-block-start: 0 !important;
}

/* ==================================================
 STICKY HEADER SHELL — FINAL
 UNIQUE ANCHOR: STICKY-HEADER-SHELL-FINAL-2026
 ================================================== */

.campaign-sticky-shell {
 position: sticky !important;
 top: 0 !important;
 z-index: 9999 !important;

 width: 100vw !important;
 max-width: 100vw !important;

 margin-left: calc(50% - 50vw) !important;
 margin-right: calc(50% - 50vw) !important;
 margin-top: 0 !important;
 margin-bottom: 0 !important;

 padding: 0 !important;

 background: rgba(255, 255, 255, 0.84) !important;

-webkit-backdrop-filter: blur(8px) !important;
backdrop-filter: blur(8px) !important;

 box-shadow: 0 5px 14px rgba(0, 0, 0, 0.10) !important;
}

/* ==================================================
 STICKY HEADER — ADMIN BAR OFFSET
 UNIQUE ANCHOR: STICKY-SHELL-ADMIN-2026
 ================================================== */

body.admin-bar .campaign-sticky-shell {
 top: 32px !important;
}

@media (max-width: 782px) {

 body.admin-bar .campaign-sticky-shell {
 top: 46px !important;
 }
}

/* ==================================================
 MOBILE — DISABLE STICKY HEADER
 UNIQUE ANCHOR: MOBILE-STICKY-OFF-2026
 ================================================== */

@media (max-width: 700px) {

 .campaign-sticky-shell {
 position: relative !important;
 top: auto !important;

 /* Keep header/menu above banner and page content */
 z-index: 9999 !important;
 }

 body.admin-bar .campaign-sticky-shell {
 top: auto !important;
 }

 .campaign-actions .gt_float_switcher {
 position: relative !important;
 z-index: 10000 !important;
 }

 .campaign-actions .gt_float_switcher .gt_options,
 .campaign-actions .gt_float_switcher .gt_options.gt-open {
 z-index: 10001 !important;
 }
}

/* ==================================================
 GTRANSLATE FLOAT MENU — OVERLAY
 UNIQUE ANCHOR: GTRANSLATE-FLOAT-OVERLAY-2026
 ================================================== */

.campaign-actions .gt_float_switcher {
 position: relative !important;
 overflow: visible !important;
}


/* LANGUAGE OPTIONS MUST FLOAT OVER PAGE */
.campaign-actions .gt_float_switcher .gt_options,
.campaign-actions .gt_float_switcher .gt_options.gt-open {
 position: absolute !important;

 top: 100% !important;
 right: 0 !important;
 left: auto !important;

 width: 180px !important;
 min-width: 180px !important;

 margin: 0 !important;

 z-index: 10050 !important;

 background: #ffffff !important;

 box-shadow: 0 5px 14px rgba(0, 0, 0, 0.12) !important;
}


/* DO NOT LET TRANSLATOR WRAPPERS CLIP THE MENU */
.campaign-actions,
.campaign-actions .wp-block-shortcode,
.campaign-actions .gtranslate_wrapper {
 overflow: visible !important;
}


